// 14-day windows covering the period the stuck rows could have been scheduled in.
const out = [];
let cur = DateTime.fromISO('2026-07-01T00:00:00');
const end = DateTime.fromISO('2026-12-31T23:59:59');
while (cur < end) {
  const winEnd = DateTime.min(cur.plus({ days: 13 }).endOf('day'), end);
  out.push({ json: { start: cur.toFormat("yyyy-LL-dd'T'HH:mm:ss"), end: winEnd.toFormat("yyyy-LL-dd'T'HH:mm:ss") } });
  cur = cur.plus({ days: 14 }).startOf('day');
}
return out;

// 1-day windows from July 1 to tomorrow. Tailwind needs a start and end date and returns at most 100 posts per call,
// so a busy week would be cut off; one day at a time never reaches the limit.
const out = [];
let cur = DateTime.fromISO('2026-07-01T00:00:00', { zone: 'utc' });
const end = DateTime.utc().plus({ days: 1 });
while (cur < end) {
  const we = DateTime.min(cur.plus({ days: 1 }), end);
  out.push({ json: { start: cur.toUTC().toISO(), end: we.toUTC().toISO() } });
  cur = we;
}
return out;

// READ-ONLY planner. Looks at every row with Status = Scheduled, finds its real Metricool post and decides:
//   PUBLISHED in Metricool  -> mark the row Published (Pin URL, Pinned Time, Post ID)
//   ERROR, same photo already published to the same board -> mark Duplicate (never resent)
//   ERROR, otherwise        -> back to Review + a new free slot (only when resendFailed = true)
//   PENDING, row missing its Post ID or Scheduled Date -> fill ONLY those blank cells from the Metricool post (backfill)
//   PENDING / not found     -> left alone (reported)
const cfg = $('Config').first().json;
const str = v => (v == null ? '' : String(v).trim());
const norm = v => str(v).toLowerCase();
const hoursOf = s => String(s).split(',').map(h => parseInt(h.trim(), 10)).filter(h => !isNaN(h));
function colLetter(i) { let s = ''; i++; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; }
function parseDate(v) {
  const s = str(v); if (!s) return null;
  for (const f of ['yyyy-LL-dd HH:mm', 'yyyy-LL-dd H:mm', 'M/d/yyyy HH:mm:ss', 'M/d/yyyy H:mm:ss', 'M/d/yyyy H:mm']) { const dt = DateTime.fromFormat(s, f); if (dt.isValid) return dt; }
  const d = new Date(s); return isNaN(d.getTime()) ? null : DateTime.fromJSDate(d);
}
// Metricool posts, by id and by uuid (uuids are huge numbers: compare as doubles, exactly like the sheet link is parsed)
const byId = new Map(), byUuid = new Map();
let windowErrors = 0;
for (const it of $('Get Metricool Posts').all()) {
  const j = it.json || {};
  if (j.error) { windowErrors++; continue; }
  const list = Array.isArray(j.data) ? j.data : Array.isArray(j.posts) ? j.posts : Array.isArray(j) ? j : (j.id ? [j] : []);
  for (const p of list) { if (p.id != null) byId.set(String(p.id), p); if (p.uuid != null) byUuid.set(String(Number(p.uuid)), p); }
}
// Tailwind (the old scheduler) may already have published a pin the sheet never recorded. Match: same title AND same
// product/blog page. Only Tailwind pins whose pin id is NOT already in the sheet are used, and each can be claimed once.
const normT = v => str(v).toLowerCase().replace(/\s+/g, ' ').trim();
const normU = v => str(v).toLowerCase().split('?')[0].replace(/\/+$/, '');
const twPosts = new Map(); let twWindowErrors = 0, twWindowsAtLimit = 0;
for (const it of $('Get Tailwind Sent Posts').all()) {
  const j = it.json || {};
  if (j.error) { twWindowErrors++; continue; }
  const list = (j.data && Array.isArray(j.data.posts)) ? j.data.posts : (Array.isArray(j.posts) ? j.posts : []);
  if (list.length >= 100) twWindowsAtLimit++;
  for (const p of list) if (p.id && p.pinId) twPosts.set(String(p.id), p);
}
const sheetPinIds = new Set();
const tabs = [
  { key: 'blog', name: cfg.pinsTab, rows: $('Get Pins').all(), header: $('Get Header (Blog)').first().json, perDay: Number(cfg.blogPerDay), hours: hoursOf(cfg.blogHours), minute: Number(cfg.blogMinute) },
  { key: 'photo', name: cfg.pinsTab2, rows: $('Get Pins 2').all(), header: $('Get Header (2:3)').first().json, perDay: Number(cfg.photoPerDay), hours: hoursOf(cfg.photoHours), minute: Number(cfg.photoMinute) }
];
for (const t0 of tabs) for (const it of t0.rows) { const m = /pin\/(\d+)/.exec(str((it.json || {})['Pin URL'])); if (m) sheetPinIds.add(m[1]); }
const twByKey = new Map();
for (const tp of twPosts.values()) {
  if (sheetPinIds.has(String(tp.pinId))) continue;           // already recorded in a row
  const k = normT(tp.title) + '|' + normU(tp.url);
  if (!twByKey.has(k)) twByKey.set(k, []);
  twByKey.get(k).push(tp);
}
const reslotOverdue = cfg.reslotOverdueReview === true, resendFailed = cfg.resendFailed === true, resetUnmatched = cfg.resetUnmatched === true, deleteErrored = cfg.deleteErroredPosts === true;
const summary = { dryRun: cfg.dryRun !== false, resendFailed, reslotOverdueReview: reslotOverdue, resetUnmatched, deleteErroredPosts: deleteErrored, metricoolPostsFound: byId.size, metricoolWindowErrors: windowErrors, tailwindSentPostsFound: twPosts.size, tailwindPinsNotInSheet: [...twByKey.values()].reduce((a, v) => a + v.length, 0), tailwindWindowErrors: twWindowErrors, tailwindWindowsAtLimit: twWindowsAtLimit, tabs: {} };
const writes = [], deletes = [];
const pinnedIso = (post) => {
  const pd = post.publicationDate || {}; if (!pd.dateTime) return '';
  const dt = DateTime.fromISO(pd.dateTime, { zone: pd.timezone || 'utc' });
  return dt.isValid ? dt.toUTC().toFormat("yyyy-LL-dd'T'HH:mm:ss'Z'") : '';
};

for (const t of tabs) {
  const headers = ((t.header.values || [[]])[0] || []).map(h => str(h));
  const col = {}; headers.forEach((h, i) => { if (h && !(h in col)) col[h] = colLetter(i); });
  const rows = t.rows.map(i => i.json || {}).filter(r => r['row_number'] != null);
  // A pin is a duplicate only when the SAME photo is already published to the SAME board. The same photo on a
  // different board is a deliberate re-pin (allowed for Manual Blogs) and must still be sent.
  const imgKey = r => (str(r['Image File ID']) || str(r['Image 1 URL']).split('?')[0]);
  const dupKey = r => imgKey(r) ? imgKey(r) + '|' + (str(r['Board ID']) || str(r['Board'])) : '';
  const pubKeys = new Set(rows.filter(r => norm(r['Status']) === 'published' && dupKey(r)).map(dupKey));
  const s = { heldTailwindProduct: 0, tailwindAlreadyPosted: 0, checkByHand: 0, overdueReview: 0, reslot: 0, reslotHeld: 0, scanned: 0, pending: 0, backfill: 0, markPublished: 0, publishedNoUrl: 0, duplicates: 0, resend: 0, resendHeld: 0, unmatched: 0, unmatchedDuplicate: 0, other: 0, missingColumns: [], samples: { backfill: [], markPublished: [], resend: [], duplicates: [], unmatched: [], checkByHand: [], tailwind: [], heldTailwindProduct: [] } };
  const act = []; // {row, kind, post?}
  for (const r of rows) {
    if (norm(r['Status']) !== 'scheduled') continue;
    if (norm(r['Platform']) === 'tailwind' || str(r['Tailwind Post ID'])) { s.other++; continue; }
    s.scanned++;
    const id = str(r['Metricool Post ID']);
    const um = /openWithPostUuid=(-?\d+)/.exec(str(r['Metricool Link']));
    const post = (id && byId.get(id)) || (um && byUuid.get(String(Number(um[1])))) || null;
    const claimTw = () => { const kk = normT(r['Pin Title']) + '|' + normU(r['Product Link'] || r['Blog Link']); const arr = twByKey.get(kk); return arr && arr.length ? arr.shift() : null; };
    const k = dupKey(r), dup = !!(k && pubKeys.has(k));
    if (!post) {
      const twm = claimTw();
      if (twm) { act.push({ r, kind: 'tailwind', tw: twm }); continue; }
      s.unmatched++; if (dup) s.unmatchedDuplicate++;
      if (s.samples.unmatched.length < 4) s.samples.unmatched.push({ row: r['row_number'], pin: str(r['Pin ID']).slice(0, 30), photoPublishedElsewhere: dup });
      if (resetUnmatched) act.push({ r, kind: dup ? 'duplicate' : 'resend' });
      continue;
    }
    const prov = (post.providers || []).find(x => String(x.network).toLowerCase() === 'pinterest') || (post.providers || [])[0] || {};
    const st = String(prov.status || '').toUpperCase();
    if (st === 'PUBLISHED') {
      if (!prov.publicUrl) { s.publishedNoUrl++; continue; }
      act.push({ r, kind: 'published', post, prov });
    } else if (st === 'ERROR') {
      // Only resend when the failure clearly happened BEFORE anything was published (not connected, limit reached,
      // login problem). A timeout or "pin not found" can mean Pinterest created the pin anyway: check those by hand.
      const twe = claimTw();
      if (twe) { act.push({ r, kind: 'tailwind', tw: twe, post }); continue; }
      const sure = /disconnect|account limit|monthly|quota|authoriz|token/i.test(String(prov.detailedStatus || ''));
      if (!sure) { s.checkByHand++; if (s.samples.checkByHand.length < 4) s.samples.checkByHand.push({ row: r['row_number'], pin: str(r['Pin ID']).slice(0, 30), reason: String(prov.detailedStatus || '').slice(0, 70) }); continue; }
      act.push({ r, kind: dup ? 'duplicate' : 'resend', post });
    } else {
      s.pending++;
      if (!id || !parseDate(r['Scheduled Date'])) act.push({ r, kind: 'backfill', post, prov });
    }
  }
  // slot allocator for resends: free slots from tomorrow on, never above perDay, existing future rows count
  // Hold-back for anything the exact title match could not settle: if Tailwind has a pin for the SAME product/blog page
  // that no row claimed, rows of that page are NOT resent (one of them may be that pin). Better a pin held than posted twice.
  const unclaimedByUrl = {};
  for (const arr of twByKey.values()) for (const tp of arr) { const u = normU(tp.url); if (u) unclaimedByUrl[u] = (unclaimedByUrl[u] || 0) + 1; }
  for (const a of act) {
    if (a.kind !== 'resend') continue;
    const u = normU(a.r['Product Link'] || a.r['Blog Link']);
    if (u && unclaimedByUrl[u] > 0) a.kind = 'heldTailwind';
  }
  const resetRows = new Set(act.filter(a => a.kind !== 'published').map(a => a.r['row_number']));
  const dayCount = {};
  for (const r of rows) {
    if (resetRows.has(r['row_number'])) continue;
    const stt = norm(r['Status']); if (stt === 'published' || stt === 'duplicate') continue;
    const dt = parseDate(r['Scheduled Date']); if (!dt || dt <= $now) continue;
    const key = dt.toFormat('yyyy-LL-dd'); (dayCount[key] = dayCount[key] || []).push(dt.hour);
  }
  const startDay = $now.plus({ days: Number(cfg.startDayOffset) || 1 }).startOf('day');
  function nextSlot() {
    let day = startDay;
    for (let g = 0; g < 730; g++, day = day.plus({ days: 1 })) {
      const key = day.toFormat('yyyy-LL-dd'); const taken = dayCount[key] || [];
      if (taken.length >= t.perDay) continue;
      const h = t.hours.find(x => !taken.includes(x)); if (h === undefined) continue;
      taken.push(h); dayCount[key] = taken;
      return day.set({ hour: h, minute: t.minute, second: 0, millisecond: 0 }).toFormat('yyyy-LL-dd HH:mm');
    }
    return '';
  }
  const slots = [];
  const cells = (row, obj) => {
    for (const [field, value] of Object.entries(obj)) {
      if (!col[field]) { if (!s.missingColumns.includes(field)) s.missingColumns.push(field); continue; }
      writes.push({ range: "'" + t.name.replace(/'/g, "''") + "'!" + col[field] + row, values: [[value]] });
    }
  };
  act.sort((a, b) => a.r['row_number'] - b.r['row_number']);
  for (const a of act) {
    const row = a.r['row_number'], sample = { row, pin: str(a.r['Pin ID']).slice(0, 30) };
    if (a.kind === 'heldTailwind') {
      s.heldTailwindProduct++; if (s.samples.heldTailwindProduct.length < 4) s.samples.heldTailwindProduct.push({ ...sample, page: String(a.r['Product Link'] || a.r['Blog Link']).slice(0, 70) });
      continue;
    }
    if (a.kind === 'backfill') {
      const pd = a.post.publicationDate || {};
      const when = pd.dateTime ? DateTime.fromISO(pd.dateTime, { zone: pd.timezone || 'utc' }) : null;
      const fill = {};
      if (!str(a.r['Metricool Post ID'])) fill['Metricool Post ID'] = String(a.post.id);
      if (!parseDate(a.r['Scheduled Date']) && when && when.isValid) fill['Scheduled Date'] = when.setZone('America/Toronto').toFormat('M/d/yyyy HH:mm:ss');
      if (!str(a.r['Platform'])) fill['Platform'] = 'Metricool';
      if (!Object.keys(fill).length) continue;
      s.backfill++; if (s.samples.backfill.length < 4) s.samples.backfill.push({ ...sample, fill });
      cells(row, fill);
      continue;
    }
    if (a.kind === 'tailwind') {
      s.tailwindAlreadyPosted++; const sentIso = DateTime.fromSeconds(Number(a.tw.sentAt) > 1e12 ? Number(a.tw.sentAt) / 1000 : Number(a.tw.sentAt), { zone: 'utc' }).toFormat("yyyy-LL-dd'T'HH:mm:ss'Z'");
      if (s.samples.tailwind.length < 4) s.samples.tailwind.push({ ...sample, pinId: String(a.tw.pinId), sent: sentIso });
      cells(row, { 'Status': 'Published', 'Pin URL': 'https://www.pinterest.com/pin/' + a.tw.pinId + '/', 'Pinned Time': sentIso, 'Platform': 'Tailwind', 'Tailwind Post ID': String(a.tw.id), 'Metricool Post ID': '', 'Metricool Link': '', 'Scheduled Date': '', 'Error': '' });
      if (deleteErrored && a.post) deletes.push(String(a.post.id));
    } else if (a.kind === 'published') {
      s.markPublished++; if (s.samples.markPublished.length < 4) s.samples.markPublished.push({ ...sample, url: String(a.prov.publicUrl).slice(0, 50) });
      cells(row, { 'Status': 'Published', 'Metricool Post ID': String(a.post.id), 'Pin URL': a.prov.publicUrl, 'Pinned Time': pinnedIso(a.post), 'Platform': 'Metricool', 'Scheduled Date': '', 'Error': '' });
    } else if (a.kind === 'duplicate') {
      s.duplicates++; if (s.samples.duplicates.length < 4) s.samples.duplicates.push(sample);
      cells(row, { 'Status': 'Duplicate', 'Error': 'Same photo is already published to the same board', 'Scheduled Date': '', 'Metricool Post ID': '', 'Metricool Link': '' });
      if (deleteErrored && a.post) deletes.push(String(a.post.id));
    } else {
      const canResend = resendFailed && (t.key !== 'photo' || cfg.resendPhoto === true);
      if (!canResend) { s.resendHeld++; if (s.samples.resend.length < 4) s.samples.resend.push({ ...sample, plan: t.key === 'photo' ? 'held until resendFailed and resendPhoto are true' : 'held until resendFailed = true' }); continue; }
      const slot = nextSlot(); slots.push(slot);
      s.resend++; if (s.samples.resend.length < 4) s.samples.resend.push({ ...sample, newSlot: slot });
      cells(row, { 'Status': 'Review', 'Approval': 'Approved', 'Metricool Post ID': '', 'Metricool Link': '', 'Platform': '', 'Error': '', 'Scheduled Date': slot });
      if (deleteErrored && a.post) deletes.push(String(a.post.id));
    }
  }
  // Approved rows already in Review whose slot has passed (or never had one). The publish workflow would give EVERY such
  // row a slot 24 h from now at 20-minute spacing, 25 per run, which bunches far more than 15 a day. Give them proper
  // slots here instead, after the resends, so the daily limit holds.
  const overdue = rows.filter(r => norm(r['Status']) === 'review' && norm(r['Approval']) === 'approved' && !resetRows.has(r['row_number']) && (() => { const d = parseDate(r['Scheduled Date']); return !d || d <= $now.plus({ minutes: 15 }); })())
    .sort((a, b) => a['row_number'] - b['row_number']);
  s.overdueReview = overdue.length;
  if (reslotOverdue) {
    for (const r of overdue) { const slot = nextSlot(); if (!slot) continue; slots.push(slot); s.reslot++; cells(r['row_number'], { 'Scheduled Date': slot }); }
  } else s.reslotHeld = overdue.length;
  if (slots.length) { slots.sort(); s.firstSlot = slots[0]; s.lastSlot = slots[slots.length - 1]; s.daysSpanned = new Set(slots.map(x => x.slice(0, 10))).size; }
  summary.tabs[t.name] = s;
}
summary.cellWrites = writes.length; summary.erroredPostsToDelete = deletes.length;
return [{ json: { summary, writes, deletes: [...new Set(deletes)] } }];

const plan = $('Plan Repair').first().json;
const blocked = plan.summary.dryRun === false && (plan.summary.metricoolWindowErrors > 0 || plan.summary.tailwindWindowErrors > 0);
return [{ json: { mode: blocked ? 'NOT APPLIED - a Metricool or Tailwind date window failed to load (see metricoolWindowErrors / tailwindWindowErrors), so some rows could look unmatched. Nothing was written. Run again.' : 'DRY RUN - nothing was written, nothing was deleted', summary: plan.summary } }];

// Sheets API batchUpdate takes many ranges per call. 400 cells per call keeps each request small.
const writes = $('Plan Repair').first().json.writes || [];
const sheetId = $('Config').first().json.sheetId;
const out = [];
for (let i = 0; i < writes.length; i += 400) out.push({ json: { sheetId, body: { valueInputOption: 'RAW', data: writes.slice(i, i + 400) } } });
return out.length ? out : [{ json: { sheetId, body: { valueInputOption: 'RAW', data: [] }, empty: true } }];

// How many write calls went through.
const res = $input.all().map(i => i.json || {});
const failed = res.filter(r => r.error || r.message).length;
return [{ json: { writeCalls: res.length, writeCallsFailed: failed } }];

const cfg = $('Config').first().json;
const ids = $('Plan Repair').first().json.deletes || [];
if (cfg.deleteErroredPosts === true && ids.length) return ids.map(postId => ({ json: { postId } }));
return [{ json: { skip: true } }];

const plan = $('Plan Repair').first().json;
const wr = $('Collect Write Results').first().json;
const items = $input.all().map(i => i.json || {});
const skipped = items.length === 1 && items[0].skip === true;
const delFailed = skipped ? 0 : items.filter(i => i.error || i.message).length;
return [{ json: { mode: 'APPLIED', writeCalls: wr.writeCalls, writeCallsFailed: wr.writeCallsFailed, erroredPostsDeleted: skipped ? 0 : items.length - delFailed, erroredPostDeletesFailed: delFailed, summary: plan.summary } }];
